llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Fentanyl, a structurally related tertiary-amide opioid with a basic amine and phenyl groups, has an absolute oral bioavailability of 31% after swallowed oral administration, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Fexofenadine, a P-gp substrate with diphenyl and basic amine features, has an absolute bioavailability of 41 ± 8.5% at a microdose and about 30% at therapeutic doses, showing that P-gp liability does not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Ebastine, a lipophilic BCS-II antihistamine containing diphenyl and basic piperidine motifs, achieves about 40% oral bioavailability, supporting high F for a similar lipophilic basic amide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Doxapram, a diphenyl-substituted lactam with a basic amine, has about 60% oral bioavailability in healthy adults, supporting high F for the query's diphenyl amide/amine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Loperamide, a diphenylacetamide opioid with a basic amine and hydroxyl, has an absolute oral bioavailability of only 0.3% due to P-gp efflux and first-pass metabolism, providing a structurally relevant low-F counterexample.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Terfenadine, a highly lipophilic diphenyl basic alcohol, has oral bioavailability below 2% due to extensive first-pass metabolism, another structurally relevant low-F example.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of direct oral-availability measurements from structurally related lipophilic amide/amine drugs (fentanyl ~31%, fexofenadine ~30-41%, ebastine ~40%, doxapram ~60%) supports F ≥ 20%. The low-F analogues (loperamide 0.3%, terfenadine <2%) are relevant but carry specific P-gp/CYP3A4 liabilities and have lower structural transfer; on balance, high is better supported.",
  "evidence_gaps": [
    "No direct experimental pharmacokinetic data exist for the query molecule itself.",
    "Uncertainty remains whether the query's diphenylacetamide/pyrrolidinol motif is a strong P-gp or CYP3A4 substrate like loperamide/terfenadine.",
    "Morgan similarities are modest (0.27-0.32), limiting quantitative transfer from any single analogue."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

